export function fistPump(remaining){if(remaining<=0)return 0;const t=2.2-remaining;return Math.max(0,Math.min(1,t/.25,(2.2-t)/.4))*(.82+.18*Math.sin(Math.max(0,t-.3)*Math.PI*4));}
export function victorySummary(match,opponent='Opponent'){return {title:match.winner===0?'The match is yours!':`${opponent} wins the match`,score:`${match.sets[0]}–${match.sets[1]} in sets`,detail:match.completedSets.map((g,i)=>`Set ${i+1}: ${g[0]}–${g[1]}`).join(' · ')};}
export function showVictory(match,opponent,root=document){const summary=victorySummary(match,opponent);root.querySelector('#victoryTitle').textContent=summary.title;root.querySelector('#victoryScore').textContent=summary.score;root.querySelector('#victoryDetail').textContent=summary.detail;root.querySelector('#victoryTag').textContent=match.winner===0?'GAME. SET. MATCH.':'MATCH COMPLETE';const tray=root.querySelector('#victoryConfetti');tray.replaceChildren();for(let i=0;i<48;i++){const p=root.createElement('i');p.style.setProperty('--x',`${(i*37)%100}%`);p.style.setProperty('--delay',`${(i%12)*.12}s`);p.style.setProperty('--turn',`${i*47}deg`);p.style.background=['#e2bf73','#eee5c7','#7b9c83'][i%3];tray.append(p);}root.querySelector('#matchVictory').classList.remove('hidden');root.querySelector('#victoryReplay').focus();}
